import math

# Waypoints: Adjusted for better gate navigation and thermal safety
TX_MIN, TX_MAX = 28.0, 32.0
TY_MIN, TY_MAX = 2.0, 5.0
TARGET_X, TARGET_Y = 30.0, 3.5

# Gate waypoints: G1_Y adjusted to 2.6 (upper bound of [1.0, 2.8])
G1_X, G1_Y = 13.0, 2.6
G2_X, G2_Y = 23.0, 2.4  # Middle of [1.8, 3.0]

DRAIN_LO, DRAIN_HI = 14.5, 17.0
SLIP_LO, SLIP_HI = 17.5, 20.0
WIND_LO, WIND_HI = 20.5, 28.0
WIND_AMP = 20.0
WIND_OMEGA = 0.055

# Thrust values for better progress without exceeding thermal limits
MAX_THRUST = 70.0
LOW_THRUST = 50.0
HEAT_SAFE_FRAC = 0.85  # Earlier reduction for safety

def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)

def build_agent(sandbox):
    return None  # No physical structure needed for this controller

def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return
    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat
    step_idx = sandbox.get_step_count()

    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 40.0)  # Small thrust to ensure centering
        return

    if x > 31.0 and y < 2.0:
        sandbox.apply_thrust(-90.0, 120.0)
        return

    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.2)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.3)

    if overheat_limit <= 40000.0:
        heat_frac = heat / overheat_limit
        if heat_frac > 0.3:
            thrust_mag = 40.0
        else:
            thrust_mag = 50.0

    if x < 10.0:
        thrust_mag = min(60.0, thrust_mag)
    if 10.0 <= x <= 15.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.2)
    if DRAIN_LO <= x <= DRAIN_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.2)
    if SLIP_LO <= x <= SLIP_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.1)
    if WIND_LO <= x <= WIND_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.15)

    if thrust_mag < 40.0 and overheat_limit > 40000.0:
        sandbox.apply_thrust(0.0, 40.0)
        return

    wx, wy = _waypoint(x, y)
    if x > 24.0:
        wy = 4.0  # Ensure higher clearance for wind and final approach
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 40.0)
        return

    ux = dx / dist
    uy = dy / dist
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    if y < 1.4:
        fy += 30.0  # Reduced vertical lift
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(15.0, (1.2 - y) * 20.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 60.0  # Help counteract wind and drag
    if x > 25.0 and y < 3.0:
        fy += 60.0
    if SLIP_LO <= x <= SLIP_HI:
        fx += 15.0
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy -= wind_fy  # Compensate for wind

    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 1.8  # Slightly higher cap to allow more thrust when needed

    if y < 1.4:
        cap = max(cap, 100.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        cap = max(cap, 150.0)

    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    # Small forward thrust if the craft is stuck or moving too slowly
    if abs(agent_body.linearVelocity.x) < 0.1 and x > 8.0 and x < 25.0:
        fx += 10.0

    sandbox.apply_thrust(fx, fy)
